mapper.select:
select t.hours,t.machine_id,t.machine_id machineId,t.min,t.status_cd,t.status_cd statusCd,t.lmo_id,t.lmo_id
lmoId,t.type, lm.machine_code machineCode, lm.machine_name machineName, td.name typeName
from lamp_machine_open_close t
left join lamp_machine lm on t.machine_id = lm.machine_id and lm.status_cd = '0'
left join t_dict td on t.type = td.status_cd and td.table_name = 'lamp_machine_operation' and td.table_columns = 'type'
where 1 =1

    and t.hours= #{hours}


    and t.machine_id= #{machineId}


    and t.min= #{min}


    and t.status_cd= #{statusCd}


    and t.lmo_id= #{lmoId}


    and t.type= #{type}


    and lm.machine_name like concat('%', #{machineName}, '%')


    and lm.machine_code like concat('%', #{machineCode}, '%')

order by t.create_time desc

    limit #{page}, #{row}

